ERR = 'ERROR: '

class HostError(Exception): "A host refusal."

def host_err(e):
    "A caught exception, for a user-facing surface."
    return f'{type(e).__name__}: {e}'

def err(what, e=None):
    "One tool failure, spelled the way every other tool spells it."
    return f'{ERR}{what}' + (f': {host_err(e)}' if e is not None else '')

def failed(result):
    "Whether a tool result starts with `ERROR: `."
    return str(result or '').startswith(ERR)

class Media(str):
    "A tool result's text carrying pictures, as paths or bytes, that the agent's loop sends the model after it."
    def __new__(cls, text='', media=()):
        o = super().__new__(cls, text); o.media = list(media); return o

def attempt(what, f):
    "Run `f`; a host that cannot is left to raise, and anything else is one tool failure."
    try: return f()
    except NotImplementedError: raise
    except Exception as e: return err(what, e)

