WITHHELD = 'withheld'

class ReadCheck:
    "One read a `read_guard` decides on. `text` loads on first use, so a guard deciding on `path` alone reads nothing."
    def __init__(self, path, tool='', kind='text', load=None, model='', local=None): store_attr()
    @functools.cached_property
    def text(self): return None if self.load is None else self.load()
    def __repr__(self): return f'ReadCheck({self.path!r}, tool={self.tool!r}, kind={self.kind!r}, model={self.model!r}, local={self.local})'

class Refusal(AttrDict):
    "A `read_guard` withholding a read: `why` the model is told, `kind` a caller branches on, the `path` refused."
    def __init__(self, why, kind=WITHHELD, path=''): super().__init__(why=why, kind=kind, path=path)
    def __str__(self): return f'{ERR}{self.kind}: ' + (f'{self.path}: ' if self.path else '') + str(self.why)

def guard_read(host, path, load=None, tool='', kind='text', model=None, local=None):
    "What `host.read_guard` says of one read: None sends it as is, a str is sent instead, a `Refusal` withholds it."
    if (g := getattr(host, 'read_guard', None)) is None: return None
    path = str(path)
    if model is None or local is None:
        try: on, named = host.model_local()
        except Exception: on, named = None, ''
        model, local = ifnone(model, named), ifnone(local, on)
    try: r = g(ReadCheck(path, tool, kind, load, model, local))
    except Exception as e: return Refusal(f'the read guard failed, so nothing was sent ({host_err(e)})', 'guard_failed', path)
    if r is None or r is True: return None
    if r is False: return Refusal('this host withholds it from this model', path=path)
    if isinstance(r, Refusal): return r if r.path else Refusal(r.why, r.kind, path)
    return str(r)

def screened(host, path, text, tool='', kind='text', **kw):
    "`text` as `host.read_guard` lets it go: whole, masked, or the `Refusal`."
    r = guard_read(host, path, lambda: text, tool, kind, **kw)
    return text if r is None else r

# %% ../nbs/00_core.ipynb #a0da82f5
SANDBOX = 'path is outside the open folders'
READ_ONLY = 'path is in a folder opened for reading only'
SECRET = 'path holds credentials and is never read'
NO_ROOTS = 'no folders are open, so no path is inside them'
#: Credential-shaped paths refused even with `read_outside`. `fnmatch` on the resolved path.
DENY = ('*/.ssh/*', '*/.aws/*', '*/.gnupg/*', '*/.config/gcloud/*', '*/.netrc', '*/.git-credentials', '*/.codex/auth.json', '*/.claude/.credentials.json',
        '*/.env', '*/.env.*', '*/id_rsa*', '*/id_ed25519*', '*.pem', '*.key', '*.p12')
class Unsafe(HostError): "A path that resolves outside every open root, or one refused for safety."

def denied(path, patterns=DENY):
    "Whether `path` matches a refused credential path, in any case: a case-insensitive disk opens `.SSH` as `.ssh`."
    s = Path(path).as_posix().lower()
    return any(fnmatch(s, pat.lower()) for pat in patterns)

