_SPILL, _SPILL_LOCK = [], threading.Lock()   # this process's spill folder, made on first use

def spill_dir():
    "The folder results too long to send whole are saved in: one per process, private to this OS user, readable and never writable through every `Sandbox` in the process. File names are random."
    with _SPILL_LOCK:
        if not _SPILL: _SPILL.append(Path(tempfile.mkdtemp(prefix='shalya-spill-')).resolve())
    return _SPILL[0]

def spill(text):
    "Save `text` whole in `spill_dir`, and return its path."
    p = spill_dir()/f'{uuid.uuid4().hex[:12]}.txt'
    p.write_text(str(text), encoding='utf-8')
    return p

class Sandbox:
    "The open folders, and the one place that decides whether a path is inside them."
    def __init__(self,
                 roots=(),             # folders to open for reads and writes; each must already exist
                 read_outside=False,   # let reads name any path on this machine
                 deny=DENY,            # what `read_outside` still refuses to open
                 read_roots=()):       # folders to open for reads only
        self.roots, self.read_roots, self.read_outside, self.deny = L(), L(), bool(read_outside), tuple(deny or ())
        for r in roots: self.add_root(r)
        for r in read_roots: self.add_root(r, readonly=True)
    def __repr__(self): return f'Sandbox({[str(r) for r in self.roots]}' + (f', read_roots={[str(r) for r in self.read_roots]})' if self.read_roots else ')')
    def covers(self, p):
        "Whether `p` is inside a root open for writes, or is one of them."
        return any(Path(p).is_relative_to(r) for r in self.roots)
    def reads(self, p):
        "Whether `p` is inside a root open for reads only."
        return any(Path(p).is_relative_to(r) for r in self.read_roots)
    def add_root(self, p, readonly=False):
        "Open a folder, for reads only when `readonly`, closing any root of that kind inside it. Returns the root that now covers it."
        p = Path(p).expanduser().resolve()
        if not p.exists(): raise Unsafe(f'no such folder: {p}')
        if not p.is_dir(): raise Unsafe(f'not a folder, so it cannot be a root: {p}')
        if self.covers(p) or (readonly and self.reads(p)): return self.root_of(p)
        if readonly: self.read_roots = L([r for r in self.read_roots if p not in r.parents]) + [p]
        else:   # a write root also closes the read-only roots inside it, which it now covers
            self.roots = L([r for r in self.roots if p not in r.parents]) + [p]
            self.read_roots = L([r for r in self.read_roots if r != p and p not in r.parents])
        return p
    def drop_root(self, p):
        "Close a folder. Nothing under it resolves any more."
        p = Path(p).expanduser().resolve()
        self.roots, self.read_roots = self.roots.filter(lambda r: r != p), self.read_roots.filter(lambda r: r != p)
        return p
    def check(self, path, must_exist=False, reading=False):
        "Resolve `path`, and refuse it unless it lands inside an open root."
        if not (self.roots or self.read_roots): raise Unsafe(f'{NO_ROOTS}: {path}')
        p = Path(path).expanduser()
        if not p.is_absolute(): p = (self.roots or self.read_roots)[0]/p
        p = p.resolve()
        if not self.covers(p) and not (reading and _SPILL and p.is_relative_to(_SPILL[0])):
            if self.reads(p):
                if not reading: raise Unsafe(f'{READ_ONLY}: {p}')
                if denied(p, self.deny): raise Unsafe(f'{SECRET}: {p}')   # a read root as wide as `~` must not open `.ssh`
                if must_exist and not p.exists(): raise Unsafe(f'no such file: {p}')
                return p
            if not (reading and self.read_outside): raise Unsafe(f'{SANDBOX}: {p}')
            if denied(p, self.deny): raise Unsafe(f'{SECRET}: {p}')
        if must_exist and not p.exists(): raise Unsafe(f'no such file: {p}')
        return p
    def root_of(self, path):
        "The open root holding `path`, or None when `read_outside` let it through from elsewhere."
        p = self.check(path, reading=True)
        return first(r for r in (*self.roots, *self.read_roots) if p.is_relative_to(r))
    def bare(self, name):
        "A name typed by a person or a model, refused unless it is one path component."
        if '/' in name or os.sep in name or name in ('', '.', '..'): raise Unsafe(f'{name!r} is not a bare filename')
        return name
    def under(self, path, name):
        "Where an entry called `name` goes inside `path`. `name` is one component, never a path."
        return self.check(self.check(path)/self.bare(name))

