def clip(s, n=MAX_TOOL_CHARS,
         more='',      # how to read the rest, when the caller has a way
         keep=False):  # save the whole with `spill` and name the file, for a result nothing can page
    "Truncate a tool result to `n` chars, its note included, whenever `n` is longer than the note."
    s, n = str(s), max(1, int(n))   # a caller subtracting a margin can arrive at zero or less
    if len(s) <= n: return s
    if keep: more = f'full text saved to {spill(s)}; read it with view_file' + (f'; {more}' if more else '')
    note = lambda shown: f'…[truncated: {shown} of {len(s)} chars shown' + (f'. {more}]' if more else ']')
    room = max(1, n - len(note(n)))
    cut = s[:room]
    nl = cut.rfind('\n')
    if nl > room * 0.6: cut = cut[:nl]
    return cut + note(len(cut))

def clip_json(r, n=MAX_TOOL_CHARS):
    """`r` as indented JSON that stays JSON within `n`, whenever `n` is longer than the note: whole when it fits;
    a dict as its plain fields, the longest strings shortened, with a `truncated` note; a list as the items that
    fit and a last item saying how many more. The note names the file that holds the whole."""
    s = json.dumps(r, indent=2)
    if len(s) <= n or not isinstance(r, (dict, list)): return clip(s, n, keep=True)
    note = f'{len(s)} chars; the whole is saved to {spill(s)}; read it with view_file'
    if isinstance(r, list):
        out = lambda k: json.dumps(r[:k] + [f'…[{len(r) - k} more; {note}]'], indent=2)
        lo, hi = 0, len(r)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if len(out(mid)) <= n: lo = mid
            else: hi = mid - 1
        return out(lo)
    plain = {k: v for k, v in r.items() if not isinstance(v, (list, dict))}
    plain['truncated'] = f"{', '.join(k for k in r if k not in plain) or 'nothing'} left out; {note}"
    while len(out := json.dumps(plain, indent=2)) > n:
        long = [k for k, v in plain.items() if k != 'truncated' and isinstance(v, str) and len(v) > 40]
        if not long: break
        k = max(long, key=lambda k: len(plain[k]))
        plain[k] = plain[k][:len(plain[k]) // 2] + '…'
    return out

# %% ../nbs/00_core.ipynb #7ca20dbc
def clip_lines(lines, start=1, n=MAX_TOOL_CHARS, more='', empty='(nothing)'):
    "Render `lines` within `n` chars, the note included whenever `n` is longer than the note, and say which line to resume from."
    lines = listify(lines)
    if not lines: return empty
    if len(whole := '\n'.join(map(str, lines))) <= n: return whole
    out, used, room = [], 0, max(1, n - 70 - len(more))   # what the note may need, from the budget
    for i, line in enumerate(lines):
        line = str(line)
        if used + len(line) + 1 > room:
            if out:
                rest = len(lines) - i
                tail = f'\n…[{rest} more line(s) not shown'
                hint = more.format(next=start + i) if '{next}' in more else more
                return '\n'.join(out) + (f'{tail}. {hint}]' if hint else f'{tail}]')
            keep, rest = max(1, room - 1), len(lines) - 1
            more_lines = f', and {rest} more line(s) not shown' if rest else ''
            return line[:keep] + f'\n…[line {start} is {len(line)} chars; {keep} shown{more_lines}]'
        out.append(line); used += len(line) + 1
    return '\n'.join(out)

# %% ../nbs/00_core.ipynb #d67ed39a
def cmds(commands):
    "Models emit JSON and exhash wants tuples, nested ones included: `[[...]]` becomes `[(...)]`."
    if isinstance(commands, str): commands = json.loads(commands)
    if not isinstance(commands, list): raise ValueError('commands must be a JSON list of command arrays')
    def _t(c):
        if not isinstance(c, (list, tuple)): raise ValueError(f'each command must be an array, got {type(c).__name__}')
        return tuple(_t(x) if isinstance(x, (list, tuple)) else x for x in c)
    return [_t(c) for c in commands]

