def edits(es):
    "`{'oldText','newText'}` dicts or `[old, new]` pairs, as a list; a JSON string of either still parses this release."
    shape = 'edits is a list of {"oldText": …, "newText": …}'
    if isinstance(es, str):
        try: es = json.loads(es)
        except Exception as e: raise ValueError(f'{shape}, not {es[:60]!r}') from e
    if isinstance(es, dict): es = [es]
    if not isinstance(es, (list, tuple)): raise ValueError(f'{shape}, got {type(es).__name__}')
    out = []
    for e in es:
        if isinstance(e, dict):
            if 'oldText' not in e or 'newText' not in e: raise ValueError("each edit needs 'oldText' and 'newText' (exact keys)")
            out.append((str(e['oldText']), str(e['newText'])))
        elif isinstance(e, (list, tuple)) and len(e) == 2: out.append((str(e[0]), str(e[1])))
        else: raise ValueError(f'each edit must be {{"oldText":…,"newText":…}} or [old, new]; {shape}')
    return out

def apply_edits(text, es):
    "Apply exact-text edits to `text`, or raise saying which one is wrong and why."
    spans = []
    for i, (old, new) in enumerate(es, 1):
        if not old: raise ValueError(f'edit {i}: oldText is empty; give the exact text to replace')
        n = text.count(old)
        if n == 0: raise ValueError(f'edit {i}: oldText not found. It must match the file exactly, including indentation. Re-read the file and try again')
        if n > 1: raise ValueError(f'edit {i}: oldText matches {n} places. Include more surrounding lines so it matches exactly one')
        at = text.index(old)
        spans.append((at, at + len(old), new, i))
    spans.sort()
    for (s1, e1, _, i1), (s2, _, _, i2) in zip(spans, spans[1:]):
        if s2 < e1: raise ValueError(f'edits {i1} and {i2} overlap; merge them into one edit')
    out, at = [], 0
    for s, e, new, _ in spans:
        out.append(text[at:s])
        out.append(new)
        at = e
    out.append(text[at:])
    return ''.join(out)

